effect.shader:
float beHashS(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }
void main() {
vec2 uv = acScreenNorm;
vec4 src = texture2DCv(inputImg.texture, uv);
vec2 g = uv * vec2(density, density * 0.5625);
vec2 cell = floor(g);
vec2 pos = fract(g) - 0.5;
float h = beHashS(cell);
float tw = 0.5 + 0.5 * sin(acTime * max(speed, 0.0) * (1.0 + h * 2.0) + h * 40.0);
float d = length(pos);
float rad = (size / max(density, 1.0)) * (0.35 + 0.65 * tw);
float m = smoothstep(rad, rad * 0.4, d) * step(0.15, h) * tw;
vec3 outRgb = mix(src.rgb, tint.rgb, clamp(m, 0.0, 1.0));
gl_FragColor = vec4(outRgb, src.a);
}
